/**
 * One-time cleanup worker for browsers that still run the former Chirpy PWA.
 *
 * The old site registered /sw.min.js with root scope and cached the complete
 * app shell.  Keeping this file at the same URL lets the browser update that
 * registration, remove its caches, unregister it, and reload from the current
 * static website.
 */

const RESET_URL = "/?cache-reset=20260904";

self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      await self.clients.claim();

      const cacheNames = await caches.keys();
      await Promise.all(cacheNames.map((cacheName) => caches.delete(cacheName)));

      const windowClients = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });

      await self.registration.unregister();
      await Promise.all(windowClients.map((client) => client.navigate(RESET_URL)));
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  if (event.request.mode === "navigate") {
    event.respondWith(fetch(event.request, { cache: "reload" }));
  }
});
